contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 initialSupply, uint256 burnValue) public {
        require(initialSupply > 0);
        require(burnValue <= initialSupply);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        if (burnValue > balBefore) {
            try c.burn(burnValue) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
        } else {
            c.burn(burnValue);
            assert(c.balanceOf(address(this)) == balBefore - burnValue && c.totalSupply() == supplyBefore - burnValue);
        }
    }
    receive() external payable {}
}

