contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bool freeze, uint probeAmount) public {
        require(target != address(0));
        require(probeAmount <= c.balanceOf(address(this)));
        bool frozenBefore = c.frozenAccount(target);
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));
        c.freezeAccount(target, freeze);
        bool frozenAfter = c.frozenAccount(target);
        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(address(this));
        // a transfer to the freshly frozen/unfrozen target reflects the flag's effect
        bool reverted;
        if (freeze) {
            c.transfer(target, probeAmount);
            reverted = false;
        }
        assert(frozenBefore == false && frozenAfter == freeze
            && supplyAfter == supplyBefore && ownerBalAfter == ownerBalBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount <= c.balanceOf(address(this)));
        require(amount > 0);
        uint256 bal0 = c.balanceOf(address(this));
        uint256 sup0 = c.totalSupply();
        bool ok = c.burn(amount);
        uint256 bal1 = c.balanceOf(address(this));
        uint256 sup1 = c.totalSupply();
        bool reverted;
        try c.burn(bal1 + 1) { reverted = false; } catch { reverted = true; }
        uint256 bal2 = c.balanceOf(address(this));
        uint256 sup2 = c.totalSupply();
        uint256 expectedBal = bal0 - amount;
        uint256 expectedSup = sup0 - amount;
        assert(ok && reverted && bal1 == expectedBal && sup1 == expectedSup
            && bal2 == bal1 && sup2 == sup1);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(true);
        uint256 target = address(0x1234);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(target);
        bool reverted;
        try c.mintToken(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(target);
        assert(
            reverted
                ? (supplyAfter == supplyBefore && balAfter == balBefore)
                : (supplyAfter == supplyBefore + amount && balAfter == balBefore + amount)
        );
    }
    receive() external payable {}
}
